const request = new XMLHttpRequest();
request.open("GET", "/api/updates");
request.responseType = "json";
request.timeout = 5000;

request.addEventListener("load", () => {
  if (request.status >= 200 && request.status < 300) {
    console.log(request.response);
  } else {
    console.error("HTTP status", request.status);
  }
});
request.addEventListener("error", () => console.error("network failure"));
request.addEventListener("timeout", () => console.error("timed out"));
request.send();

const socket = new WebSocket("wss://example.test/events");

socket.addEventListener("open", () => {
  if (socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify({ type: "subscribe", topic: "news" }));
  }
});
socket.addEventListener("message", (event) => {
  if (typeof event.data !== "string") return;
  try {
    const message = JSON.parse(event.data);
    console.log(message.type, message.payload);
  } catch {
    console.warn("unexpected non-JSON message");
  }
});
socket.addEventListener("close", (event) => console.log("closed", event.code));
socket.addEventListener("error", () => console.error("socket error"));

