const worker = new Worker(new URL("./sum.worker.js", import.meta.url), { type: "module" });

worker.addEventListener("message", ({ data }) => {
  console.log("sum:", data.total);
  worker.terminate();
});
worker.addEventListener("error", (event) => console.error(event.message));
worker.postMessage({ numbers: [1, 2, 3, 4] });

// sum.worker.js
self.addEventListener("message", ({ data }) => {
  const total = data.numbers.reduce((sum, value) => sum + value, 0);
  self.postMessage({ total });
});

// Register from the page (secure context, or localhost in development).
navigator.serviceWorker.register("/sw.js").catch(console.error);

// In sw.js: pre-cache selected static assets during install.
self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open("static-v1").then((cache) => cache.addAll(["/", "/index.html"])),
  );
});

// Intercept only same-origin GET requests; serve cache first, then network.
self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== "GET" || url.origin !== self.location.origin) return;
  event.respondWith(caches.match(event.request).then((cached) => cached ?? fetch(event.request)));
});

